    with open(file_path, 'wb') as f:
        f.write(data)
    conn = get_db_connection()
    cur = conn.cursor()
    cur.execute(
        """INSERT INTO generated_images (id, user_id, guest_id, prompt, file_path, mime_type)
           VALUES (%s, %s, %s, %s, %s, %s)""",
        (image_id, user_id, guest_id, prompt, file_path, 'image/png')
    )
    conn.commit()
    cur.close()
    conn.close()
    return file_path, str(image_id)

def generate_image_with_gemini(prompt):
    client = get_gemini_client()
    if not client:
        return None, "Gemini API kulcs nincs beállítva"

    model = "gemini-2.0-flash-preview-image-generation"
    contents = [
        types.Content(
            role="user",
            parts=[
                types.Part.from_text(text=prompt),
            ],
        ),
    ]
    generate_content_config = types.GenerateContentConfig(
        response_modalities=[
            "IMAGE",
            "TEXT",
        ],
    )

    try:
        response = client.models.generate_content(
            model=model,
            contents=contents,
            config=generate_content_config,
        )

        if not response.candidates:
            return None, "Nem sikerült képet generálni"

        content = response.candidates[0].content
        if not content or not content.parts:
            return None, "Üres válasz érkezett"

        for part in content.parts:
            if part.inline_data and part.inline_data.data:
                return part.inline_data.data, None

        return None, "Nem található kép a válaszban"
    except Exception as e:
        return None, str(e)

