@app.route('/api/auth/register', methods=['POST'])
@csrf.exempt
def register():
    data = request.get_json()
    if not data:
        return jsonify({'success': False, 'error': 'Érvénytelen kérés'}), 400
    email = data.get('email', '').strip().lower()
    password = data.get('password', '')
    if not email or '@' not in email:
        return jsonify({'success': False, 'error': 'Érvénytelen email cím'}), 400
    if len(password) < 8:
        return jsonify({
            'success': False,
            'error': 'A jelszónak legalább 8 karakter hosszúnak kell lennie'
        }), 400

    user_id = create_user(email, password)
    if user_id:
        return jsonify({'success': True, 'user_id': user_id})
    return jsonify({'success': False, 'error': 'Ez az email cím már regisztrálva van'}), 400

@app.route('/api/auth/login', methods=['POST'])
@csrf.exempt
def login():
    data = request.get_json()
    if not data:
        return jsonify({'success': False, 'error': 'Érvénytelen kérés'}), 400
    email = data.get('email', '').strip().lower()
    password = data.get('password', '')
    user_id = validate_user(email, password)
    if user_id:
        session['authenticated'] = True
        session['user_id'] = user_id
        session['is_guest'] = False
        session['email'] = email
        return jsonify({'success': True, 'user_id': user_id})
    return jsonify({
        'success': False,
        'error': 'Hibás email vagy jelszó'
    }), 401

