@csrf.exempt
def chat_stream():
    get_llm_client()
    if not llm_client:
        return jsonify({'error': 'LLM API nem elérhető'}), 503

    user_message = request.form.get('message', '')
    conversation_id = request.form.get('conversation_id')
    files = request.files.getlist('files')
    user_id = session.get('user_id')
    is_guest = session.get('is_guest', False)

    conn = get_db_connection()
    try:
        cur = conn.cursor()
        if not conversation_id:
            conversation_id = str(uuid.uuid4())
            title = user_message[:50] if user_message else 'Új beszélgetés'
            if is_guest:
                cur.execute(
                    'INSERT INTO conversations (id, guest_id, title, last_message) VALUES (%s, %s, %s, %s)',
                    (conversation_id, user_id, title, user_message[:100]),
                )
            else:
                cur.execute(
                    'INSERT INTO conversations (id, user_id, title, last_message) VALUES (%s, %s, %s, %s)',
                    (conversation_id, user_id, title, user_message[:100]),
                )
            conn.commit()

        cur.execute(
            'INSERT INTO messages (conversation_id, role, content) VALUES (%s, %s, %s)',
            (conversation_id, 'user', user_message),
        )
        cur.execute('UPDATE conversations SET last_message = %s WHERE id = %s', (user_message[:100], conversation_id))
        conn.commit()

        cur.execute(
            'SELECT role, content FROM messages WHERE conversation_id = %s ORDER BY created_at DESC LIMIT 20',
            (conversation_id,),
        )
        history_rows = cur.fetchall()
        cur.close()
    finally:
        conn.close()

    file_contents = []
    allowed_extensions = {'txt', 'md', 'json', 'csv', 'xml', 'html', 'css', 'js', 'py'}
    for f in files:
        filename = f.filename or ''
        ext = filename.rsplit('.', 1)[-1].lower() if '.' in filename else ''
        if ext in allowed_extensions:
            try:
                file_data = read_file_chunked(f, MAX_FILE_SIZE)
                content = file_data.decode('utf-8', errors='ignore')
                sanitized = sanitize_file_content(content)
                file_contents.append('[Fájl: ' + filename + ']\n' + sanitized)
            except ValueError:
                file_contents.append('[Fájl: ' + filename + '] - Túl nagy fájl')
            except Exception:
                continue

    full_message = user_message
    if file_contents:
        full_message = user_message + '\n\n' + '\n\n'.join(file_contents)

    tools = (
        [
            {
                'type': 'function',
                'function': {
                    'name': 'web_search',
                    'description': 'Keresés a weben aktuális információkért. Mindig használd friss hírek, árak, események esetén.',
                    'parameters': {
                        'type': 'object',
                        'properties': {'query': {'type': 'string', 'description': 'A keresési lekérdezés'}},
                        'required': ['query'],
                    },
                },
            }
        ]
        if exa_client
        else []
    )

    def generate():
        yield 'data: ' + json.dumps({'type': 'start', 'conversation_id': conversation_id}) + '\n\n'

        messages = [{'role': 'system', 'content': SYSTEM_PROMPT}]
        history = list(reversed(history_rows))
        for msg in history:
            messages.append({'role': msg['role'], 'content': msg['content']})
        messages.append({'role': 'user', 'content': full_message})

        full_response = ''

        try:
            while True:
                response = llm_client.chat.completions.create(
                    model=llm_model,
                    messages=messages,
                    max_tokens=8192,
                    temperature=0.14,
                    top_p=1,
                    tools=tools or None,
                    tool_choice='auto' if tools else 'none',
                )

                choice = response.choices[0]
                assistant_message = choice.message

                if assistant_message.content:
                    full_response += assistant_message.content
                    yield 'data: ' + json.dumps({'type': 'token', 'content': assistant_message.content}) + '\n\n'

                if getattr(assistant_message, 'tool_calls', None):
                    messages.append(
                        {
                            'role': 'assistant',
                            'content': assistant_message.content or '',
                            'tool_calls': [tool_call_as_dict(tc) for tc in assistant_message.tool_calls],
                        }
                    )

                    for tool_call in assistant_message.tool_calls:
                        fn = getattr(tool_call, 'function', None)
                        fn_name = getattr(fn, 'name', None)
                        if fn_name == 'web_search':
                            args = safe_json_loads(getattr(fn, 'arguments', '') or '')
                            query = (args.get('query') or '').strip()
                            if query:
                                yield 'data: ' + json.dumps({'type': 'thinking', 'content': 'Keresés indítása: ' + query}) + '\n\n'

                            result_text = 'Nincs találat.'
                            if query and exa_client:
                                try:
                                    search_results = exa_client.search(query, num_results=20)
                                    lines = []
                                    for r in getattr(search_results, 'results', [])[:20]:
                                        title = getattr(r, 'title', '') or ''
                                        url = getattr(r, 'url', '') or ''
                                        snippet = getattr(r, 'snippet', '') or getattr(r, 'text', '') or ''
                                        lines.append('Cím: ' + title)
                                        lines.append('Link: ' + url)
                                        if snippet:
                                            lines.append('Kivonat: ' + snippet[:500])
                                        lines.append('')
                                    result_text = '\n'.join(lines).strip() if lines else 'Nincs találat.'
                                except Exception as e:
                                    result_text = 'Keresési hiba: ' + str(e)

                            messages.append(
                                {
                                    'role': 'tool',
                                    'tool_call_id': getattr(tool_call, 'id', None),
                                    'name': fn_name,
                                    'content': result_text,
                                }
                            )
                else:
                    break

            conn2 = get_db_connection()
            try:
                cur2 = conn2.cursor()
                cur2.execute(
                    'INSERT INTO messages (conversation_id, role, content) VALUES (%s, %s, %s)',
                    (conversation_id, 'assistant', full_response),
                )
                conn2.commit()
                cur2.close()
            finally:
                conn2.close()

            yield 'data: ' + json.dumps({'type': 'done'}) + '\n\n'

        except Exception as e:
            error_msg = str(e) if str(e) else 'Ismeretlen hiba'
            yield 'data: ' + json.dumps({'type': 'error', 'content': 'Hiba történt: ' + error_msg}) + '\n\n'
            yield 'data: ' + json.dumps({'type': 'done'}) + '\n\n'

    return Response(
        generate(),
        mimetype='text/event-stream',
        headers={'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no'},
    )


