@csrf.exempt
def generate_image_stream():
    data = request.get_json(silent=True) or {}
    prompt = (data.get('prompt') or '').strip()
    if not prompt:
        return jsonify({'success': False, 'error': 'Prompt megadása kötelező'}), 400

    user_id = session.get('user_id')
    is_guest = session.get('is_guest', False)

    def generate():
        yield 'data: ' + json.dumps({'type': 'start', 'message': 'Kép generálása...'}) + '\n\n'

        client = get_gemini_client()
        if not client:
            yield 'data: ' + json.dumps({'type': 'error', 'message': 'Gemini API kulcs nincs beállítva'}) + '\n\n'
            yield 'data: ' + json.dumps({'type': 'done'}) + '\n\n'
            return

        model = 'gemini-2.0-flash-preview-image-generation'
        contents = [types.Content(role='user', parts=[types.Part.from_text(text=prompt)])]
        generate_content_config = types.GenerateContentConfig(response_modalities=['IMAGE', 'TEXT'])

        try:
            for chunk in client.models.generate_content_stream(model=model, contents=contents, config=generate_content_config):
                if not getattr(chunk, 'candidates', None):
                    continue
                c0 = chunk.candidates[0]
                content = getattr(c0, 'content', None)
                parts = getattr(content, 'parts', None)
                if not parts:
                    continue

                for part in parts:
                    inline = getattr(part, 'inline_data', None)
                    if inline and getattr(inline, 'data', None):
                        image_data = inline.data
                        if is_guest:
                            _, image_id = save_generated_image(image_data, prompt, guest_id=user_id)
                        else:
                            _, image_id = save_generated_image(image_data, prompt, user_id=user_id)
                        yield 'data: ' + json.dumps({'type': 'image', 'image_id': image_id, 'image_url': f'/api/image/{image_id}'}) + '\n\n'
                    elif getattr(part, 'text', None):
                        yield 'data: ' + json.dumps({'type': 'text', 'content': part.text}) + '\n\n'

            yield 'data: ' + json.dumps({'type': 'done'}) + '\n\n'
        except Exception as e:
            yield 'data: ' + json.dumps({'type': 'error', 'message': str(e)}) + '\n\n'
            yield 'data: ' + json.dumps({'type': 'done'}) + '\n\n'

    return Response(
        generate(),
        mimetype='text/event-stream',
        headers={'Cache-Control': 'no-cache', 'Connection': 'keep-alive', 'X-Accel-Buffering': 'no'},
    )


